1	// The `claim-office` command: reads a JSON scenario from stdin and writes the
2	// JSON results to stdout.
3	import { text } from "node:stream/consumers";
4	import { runScenario, type Scenario } from "./claim-office.js";
5	
6	const main = async (): Promise<void> => {
7	  const scenario = JSON.parse(await text(process.stdin)) as Scenario;
8	  process.stdout.write(JSON.stringify(runScenario(scenario)));
9	};
10	
11	// A rejected scenario is reported as a description, not a crash: the message
12	// alone goes to stderr, nothing goes to stdout, and the exit code is non-zero.
13	try {
14	  await main();
15	} catch (error) {
16	  process.stderr.write(`${(error as Error).message}\n`);
17	  process.exitCode = 1;
18	}
19

1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface QuoteStep {
11	  op: "quote";
12	  items: Item[];
13	}
14	
15	export interface Item {
16	  type: string;
17	  material?: string;
18	  enchantment?: number;
19	  cursed?: boolean;
20	}
21	
22	export interface Damage {
23	  itemType: string;
24	  amount: number;
25	}
26	
27	export interface Incident {
28	  cause: string;
29	  damages: Damage[];
30	}
31	
32	export interface ClaimStep {
33	  op: "claim";
34	  /**
35	   * Zero-based index into `Scenario.steps` of the quote step that created the
36	   * policy — not a policy id. The field name is fixed by the input schema;
37	   * `policy: 0` means "the policy quoted by steps[0]".
38	   */
39	  policy: number;
40	  incident: Incident;
41	}
42	
43	export type Step = QuoteStep | ClaimStep;
44	
45	export interface QuoteResult {
46	  premium: number;
47	}
48	
49	export interface ClaimResult {
50	  payout: number;
51	  remainingCap: number;
52	}
53	
54	export type StepResult = QuoteResult | ClaimResult;
55	
56	export interface ScenarioResult {
57	  results: StepResult[];
58	}
59	
60	const sumBy = <T>(values: T[], amountOf: (value: T) => number): number =>
61	  values.reduce((total, value) => total + amountOf(value), 0);
62	
63	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
64	  sword: 100,
65	  amulet: 60,
66	  staff: 80,
67	  potion: 40,
68	  rune: 25,
69	  moonstone: 25,
70	};
71	
72	const itemBasePremium = (item: Item): number => {
73	  const basePremium = BASE_PREMIUM_BY_TYPE[item.type];
74	  if (basePremium === undefined) {
75	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
76	  }
77	  return basePremium;
78	};
79	
80	const BLOCK_SIZE = 3;
81	
82	const BLOCK_BASE_PREMIUM = 60;
83	
84	// A block of exactly 3 alike items is priced as a unit. The block branch skips
85	// itemBasePremium, but quotePremium's surcharge pass calls it on every item, so
86	// an unknown type is still rejected — three broomsticks fail there, not here.
87	const basePremiumForSameTypeItems = (items: Item[]): number =>
88	  items.length === BLOCK_SIZE
89	    ? BLOCK_BASE_PREMIUM
90	    : sumBy(items, itemBasePremium);
91	
92	const sameTypeGroups = (items: Item[]): Item[][] => {
93	  const groupsByType = new Map<string, Item[]>();
94	  for (const item of items) {
95	    const group = groupsByType.get(item.type) ?? [];
96	    group.push(item);
97	    groupsByType.set(item.type, group);
98	  }
99	  return [...groupsByType.values()];
100	};
101	
102	const CURSE_SURCHARGE_RATE = 0.5;
103	
104	const HIGH_ENCHANTMENT_LEVEL = 5;
105	
106	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
107	
108	interface SurchargeRule {
109	  appliesTo: (item: Item) => boolean;
110	  rate: number;
111	}
112	
113	const SURCHARGE_RULES: SurchargeRule[] = [
114	  {
115	    appliesTo: (item) => item.cursed === true,
116	    rate: CURSE_SURCHARGE_RATE,
117	  },
118	  {
119	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
120	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
121	  },
122	];
123	
124	const itemSurchargeRate = (item: Item): number =>
125	  sumBy(
126	    SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)),
127	    (rule) => rule.rate,
128	  );
129	
130	const itemSurcharge = (item: Item): number =>
131	  itemBasePremium(item) * itemSurchargeRate(item);
132	
133	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
134	
135	const PROCESSING_FEE = 5;
136	
137	const LOYALTY_YEARS = 2;
138	
139	const LOYALTY_DISCOUNT_RATE = 0.2;
140	
141	const loyaltyDiscountRate = (customer: Customer): number =>
142	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT_RATE : 0;
143	
144	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
145	
146	const followUpContractDiscountRate = (precedingContracts: number): number =>
147	  precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
148	
149	// Policy-wide modifiers are rates applied to the policy base premium.
150	// Surcharges are positive rates, discounts negative ones.
151	const policyModifierRate = (
152	  customer: Customer,
153	  precedingContracts: number,
154	): number =>
155	  FIRST_INSURANCE_SURCHARGE_RATE +
156	  loyaltyDiscountRate(customer) +
157	  followUpContractDiscountRate(precedingContracts);
158	
159	const quotePremium = (
160	  step: QuoteStep,
161	  customer: Customer,
162	  precedingContracts: number,
163	): number => {
164	  const policyBasePremium = sumBy(
165	    sameTypeGroups(step.items),
166	    basePremiumForSameTypeItems,
167	  );
168	  const itemSurcharges = sumBy(step.items, itemSurcharge);
169	  // Keep this as `base + base * rate`. Factoring it to `base * (1 + rate)`
170	  // introduces IEEE-754 drift that is always upward (e.g. base 180 at rate 0.1
171	  // gives 198.00000000000003 instead of 198), and Math.ceil below turns any
172	  // such drift into a full extra G. Sword + staff would quote 204, not 203.
173	  const policyModifierAmount =
174	    policyBasePremium * policyModifierRate(customer, precedingContracts);
175	  // Rounded in the MHPCO's favour; only the final premium is rounded.
176	  return Math.ceil(
177	    policyBasePremium + itemSurcharges + policyModifierAmount + PROCESSING_FEE,
178	  );
179	};
180	
181	// Deliberately kept separate from BASE_PREMIUM_BY_TYPE. The two tables share a
182	// key domain but not a fact: an item's base premium and its insurance value are
183	// independent numbers the spec states separately. Merging them into one
184	// catalogue would couple them in the reader's mind for no gain.
185	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
186	  sword: 1000,
187	  amulet: 600,
188	  staff: 800,
189	  potion: 400,
190	  rune: 250,
191	  moonstone: 250,
192	};
193	
194	// Symmetric with itemBasePremium: both are per-item lookups that reject an
195	// unknown type rather than let `undefined` poison a sum with NaN. Callers
196	// reject unknown types before reaching here, so the throw is a guard on the
197	// declared return type, not a path any current input takes.
198	const itemInsuranceValue = (item: Item): number => {
199	  const insuranceValue = INSURANCE_VALUE_BY_TYPE[item.type];
200	  if (insuranceValue === undefined) {
201	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
202	  }
203	  return insuranceValue;
204	};
205	
206	// The block discount affects the premium only, never the insurance sum.
207	const insuranceSum = (policy: QuoteStep): number =>
208	  sumBy(policy.items, itemInsuranceValue);
209	
210	const DEDUCTIBLE = 100;
211	
212	const CAP_MULTIPLE = 2;
213	
214	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
215	
216	const REDUCED_REIMBURSEMENT_RATE = 0.5;
217	
218	const FULL_REIMBURSEMENT_RATE = 1;
219	
220	// Named for the trigger (enchantment level), to keep it distinct from the
221	// premium-side HIGH_ENCHANTMENT_LEVEL, which is a different threshold (5).
222	const reimbursementRate = (item: Item): number =>
223	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
224	    ? REDUCED_REIMBURSEMENT_RATE
225	    : FULL_REIMBURSEMENT_RATE;
226	
227	// The deductible is withheld once per damage entry, not once per incident,
228	// and applies after any reimbursement clause has reduced the amount.
229	// Clamped per entry, not on the total: a damage smaller than the deductible
230	// yields nothing, but must not eat into another damage's reimbursement.
231	const payableForDamage = (damage: Damage, item: Item): number => {
232	  const reimbursement = damage.amount * reimbursementRate(item);
233	  return Math.max(0, reimbursement - DEDUCTIBLE);
234	};
235	
236	// Which insured item a damage entry refers to. An unknown item type is
237	// rejected here too: it is simply a type the policy does not cover.
238	const insuredItemFor = (damage: Damage, policy: QuoteStep): Item => {
239	  const insured = policy.items.find((item) => item.type === damage.itemType);
240	  if (insured === undefined) {
241	    throw new Error(
242	      `The policy does not cover an item of type "${damage.itemType}"`,
243	    );
244	  }
245	  return insured;
246	};
247	
248	// Kept separate from sameTypeGroups, which groups the items themselves and
249	// discards the type key. This one needs the key, to look a type up; that one
250	// needs the members, to price a block. Merging them would distort whichever
251	// call site did not ask for the shape.
252	const countByType = <T>(
253	  values: T[],
254	  typeOf: (value: T) => string,
255	): Map<string, number> => {
256	  const counts = new Map<string, number>();
257	  for (const value of values) {
258	    const type = typeOf(value);
259	    counts.set(type, (counts.get(type) ?? 0) + 1);
260	  }
261	  return counts;
262	};
263	
264	// Distinct from the zero-clamp in payableForDamage: that handles a legitimate
265	// damage too small to clear the deductible, whereas a negative amount is not a
266	// damage at all.
267	const rejectNegativeAmounts = (damages: Damage[]): void => {
268	  for (const damage of damages) {
269	    if (damage.amount < 0) {
270	      throw new Error(
271	        `A damage amount cannot be negative, but the claim reports ${damage.amount}`,
272	      );
273	    }
274	  }
275	};
276	
277	// A damage entry is one damaged item, so a type cannot be damaged more times
278	// than the policy insures it. Checked per type across the whole incident before
279	// any settlement, because the spec rejects the claim as a whole.
280	const rejectOverClaimedTypes = (damages: Damage[], policy: QuoteStep): void => {
281	  const insuredCounts = countByType(policy.items, (item) => item.type);
282	  for (const [type, damagedCount] of countByType(
283	    damages,
284	    (damage) => damage.itemType,
285	  )) {
286	    if (damagedCount > (insuredCounts.get(type) ?? 0)) {
287	      throw new Error(
288	        `The policy covers fewer items of type "${type}" than the claim reports damaged`,
289	      );
290	    }
291	  }
292	};
293	
294	const policyCap = (policy: QuoteStep): number =>
295	  insuranceSum(policy) * CAP_MULTIPLE;
296	
297	// `step.policy` is an index into the scenario's own steps, so a malformed
298	// scenario can point it out of range or at another claim. Resolving it here
299	// turns both into the same kind of domain error every other bad input gets,
300	// rather than a TypeError downstream on `undefined.items`.
301	const policyReferencedBy = (step: ClaimStep, steps: Step[]): QuoteStep => {
302	  const referenced = steps[step.policy];
303	  if (referenced === undefined || referenced.op !== "quote") {
304	    throw new Error(
305	      `A claim must reference a quote step, but step ${step.policy} is not one`,
306	    );
307	  }
308	  return referenced;
309	};
310	
311	// The cap is a per-policy budget: a claim pays out at most what is left of it.
312	const settleClaim = (
313	  step: ClaimStep,
314	  policy: QuoteStep,
315	  capRemaining: number,
316	): ClaimResult => {
317	  rejectNegativeAmounts(step.incident.damages);
318	  rejectOverClaimedTypes(step.incident.damages, policy);
319	  const payable = sumBy(step.incident.damages, (damage) =>
320	    payableForDamage(damage, insuredItemFor(damage, policy)),
321	  );
322	  // Rounded in the MHPCO's favour — down, the opposite of the premium's
323	  // Math.ceil. Only the final payout is rounded, and the cap is decremented by
324	  // the rounded figure so the remaining cap stays in whole G.
325	  const payout = Math.floor(Math.min(payable, capRemaining));
326	  return { payout, remainingCap: capRemaining - payout };
327	};
328	
329	export const runScenario = (scenario: Scenario): ScenarioResult => {
330	  const results: StepResult[] = [];
331	  const capRemainingByPolicy = new Map<number, number>();
332	  // Only quote steps conclude a contract, so this cannot be derived from the
333	  // step index: a claim step must not earn the next quote its follow-up
334	  // discount. Incremented after pricing, so during a quote it holds the number
335	  // of contracts concluded *before* that quote — hence `preceding`.
336	  let precedingContracts = 0;
337	  for (const step of scenario.steps) {
338	    if (step.op === "quote") {
339	      results.push({
340	        premium: quotePremium(step, scenario.customer, precedingContracts),
341	      });
342	      precedingContracts += 1;
343	    } else {
344	      const policy = policyReferencedBy(step, scenario.steps);
345	      const capRemaining =
346	        capRemainingByPolicy.get(step.policy) ?? policyCap(policy);
347	      const result = settleClaim(step, policy, capRemaining);
348	      capRemainingByPolicy.set(step.policy, result.remainingCap);
349	      results.push(result);
350	    }
351	  }
352	  return { results };
353	};
